def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    strong_bids = []
    needy_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                needy_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 120:
                    strong_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0 if hp > 3 else 45.0))

    slots = max(1, int(supply // WATER_REQ))
    opp_count = len(alive_opponents)
    contest_ratio = opp_count / float(slots)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgent = hp <= 2 or no_water_days >= 2
    semi_urgent = hp <= 4 or no_water_days >= 1
    scarce = slots <= 1
    ample = slots >= 2 and supply >= 24

    if urgent:
        bid = min(budget, max(118.0, highest_prev + 4.0, DAILY_SALARY * 1.45))
        return float(max(0.0, bid))

    if scarce:
        if strong_bids:
            if semi_urgent:
                bid = min(budget, max(122.0, highest_prev + 2.0))
            else:
                bid = min(budget, 24.0)
        else:
            if contest_ratio >= 3:
                bid = min(budget, max(78.0, avg_prev + 3.0, 0.75 * DAILY_SALARY))
            else:
                bid = min(budget, max(52.0, avg_prev + 2.0))
        return float(max(0.0, bid))

    if ample:
        if highest_prev >= 120:
            bid = 16.0 if hp > 4 else 34.0
        else:
            bid = max(18.0, min(36.0, avg_prev * 0.55 if avg_prev > 0 else 22.0))
        return float(min(budget, max(0.0, bid)))

    if highest_prev >= 140:
        if semi_urgent:
            bid = min(budget, 96.0)
        else:
            bid = min(budget, 20.0)
    elif highest_prev >= 100:
        bid = min(budget, 44.0 if hp > 4 else 72.0)
    else:
        pressure = 0.0
        pressure += 8.0 if semi_urgent else 0.0
        pressure += 10.0 if needy_count >= 2 else 0.0
        pressure += 8.0 if contest_ratio >= 2.5 else 0.0
        base = max(28.0, avg_prev + 2.5 if avg_prev > 0 else 32.0)
        bid = min(budget, base + pressure)

    if day >= 8 and hp > 5 and highest_prev >= 120:
        bid = min(budget, bid * 0.85)

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents only
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents alive, spend enough to secure survival comfortably.
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace only.
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how competitive the market was yesterday.
    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = 0.0
    if len(prev_bids) >= 2:
        srt = sorted(prev_bids, reverse=True)
        second_prev = srt[1]

    # Supply pressure: if supply is low, everyone must bid more to secure water.
    # Convert to a rough number of water units needed/available.
    # Use explicit int() for indices; here only scalars.
    supply_ratio = (supply - MIN_SUPPLY) / max(1e-9, (MAX_SUPPLY - MIN_SUPPLY))
    # supply_ratio in [0,1] roughly; lower supply -> closer to 0.

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))

    # Base target bid band.
    # Yesterday highest was around 163.5 max in meta-round context, with typical high bids ~145.
    # We'll undercut slightly when supply is moderate/high; bid closer to top when supply is low or hp is critical.
    critical_hp = 2.5

    # Determine aggressiveness.
    if hp <= critical_hp:
        # Need water now.
        target = max(DAILY_SALARY * 0.75, highest_prev * 0.92) if highest_prev > 0 else DAILY_SALARY * 0.85
    else:
        # If supply is scarce, raise bid; if abundant, undercut.
        if supply_ratio < 0.35:
            target = max(DAILY_SALARY * 0.65, highest_prev * 0.88) if highest_prev > 0 else DAILY_SALARY * 0.7
        elif supply_ratio < 0.7:
            # Undercut top a bit.
            if highest_prev > 0:
                target = max(DAILY_SALARY * 0.55, highest_prev * 0.82)
            else:
                target = DAILY_SALARY * 0.6
        else:
            # Plenty of supply: conserve budget; still try to beat likely bids.
            if second_prev > 0:
                target = max(DAILY_SALARY * 0.45, second_prev * 0.98)
            elif highest_prev > 0:
                target = max(DAILY_SALARY * 0.45, highest_prev * 0.78)
            else:
                target = DAILY_SALARY * 0.5

    # Small day-based jitter (deterministic) to avoid exact ties.
    # Use day parity only.
    if int(day) % 2 == 0:
        target *= 0.995
    else:
        target *= 1.005

    # Ensure we bid at least enough to matter, but never exceed budget.
    # Also avoid bidding extremely low when hp is not great.
    min_bid = 0.15 * DAILY_SALARY
    if hp <= 4:
        min_bid = 0.35 * DAILY_SALARY

    bid = float(min(budget, max(min_bid, target)))
    # If budget is extremely low, just bid what we can.
    if bid < 0:
        bid = 0.0
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    strong_opponent_ids = ["Alex", "Eric"]

    yesterday_strong_bids = []
    for opp_id in strong_opponent_ids:
        if opp_id in opponents_status and opponents_status[opp_id]['alive']:
            opp = opponents_status[opp_id]
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_strong_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.8

    supply_factor = 1.0
    if day_context['supply'] <= 18:
        supply_factor = 1.15
    elif day_context['supply'] >= 22:
        supply_factor = 0.9

    current_bid = base_bid * supply_factor

    if yesterday_strong_bids:
        highest_strong_prev_bid = max(yesterday_strong_bids)
        if highest_strong_prev_bid >= DAILY_SALARY * 0.9:
            current_bid = max(current_bid, highest_strong_prev_bid + 5)
        elif highest_strong_prev_bid >= DAILY_SALARY * 0.7:
            current_bid = max(current_bid, highest_strong_prev_bid + 2)
        else:
            current_bid = min(current_bid, highest_strong_prev_bid + 10)

    if my_status['hp'] <= 3:
        current_bid = max(current_bid, DAILY_SALARY * 1.05)
    elif my_status['hp'] <= 5:
        current_bid = max(current_bid, DAILY_SALARY * 0.95)

    final_bid = min(my_status['budget'], current_bid)

    if my_status['hp'] <= 1:
        final_bid = max(final_bid, DAILY_SALARY * 0.9)
    elif day_context['day'] > EPISODE_DAYS - 3:
        final_bid = max(final_bid, DAILY_SALARY * 0.9)

    final_bid = max(1.0, final_bid)

    return final_bid

